    /// <summary>
    ///    Called by the kernel when a field on the table has its value modified.
    /// </summary>
    /// <param name="_fieldId">
    ///    The field ID of the field that changed.
    /// </param>
    /// <remarks>
    ///    Methods that should be called when a field value changes are called in this method.
    /// </remarks>
    public void modifiedField(FieldId _fieldId)
    {
        next modifiedField(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(InventTransferLine, ItemId):
            case fieldNum(InventTransferLine, UnitId):
            case fieldNum(InventTransferLine, InventDimId):
                this.metInventTransferLine().updateUnitFields();
                break;
                
        }
    }

/// <summary>
/// Return warehouse unit id
/// </summary>
/// <returns>Warehouse unit id</returns>
public METPOLineWarehouseUnitId metGetWarehouseUOM()
{
    return (select WarehouseUnitId from METInventTransferLine where METInventTransferLine.InventTransferLine == this.RecId).WarehouseUnitId;
}

/// <summary>
/// To calculate and display the number of cases for the sales order line quantity.
/// </summary>
/// <returns>Number of cases</returns>
[SysClientCacheDataMethod(true)]
public display METCase displayMETActualCases()
{
    return any2Int(this.metActualTotalcases());
}

    /// <summary>
    /// To calculate and display the number of broken cases for the sales order line quantity.
    /// </summary>
    /// <returns>Number of broken cases</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display METBrokenCase displayMETActualBrokenCase()
    {
        //Show broken case for each line that equals to the ordered quantity for sell units that are in "ea".
        //For any other sell units broken case=0
        //return this.SalesUnit == METConstants::unitEach ? this.SalesQty : 0;

        UnitOfMeasureSymbol     unitInvent          = InventTableModule::find(this.itemId, ModuleInventPurchSales::Invent).UnitId;
        METInventTransView      views;
        METInventTransferLine   metTransLine;

        //select * from metTransLine where metTransLine.InventTransferLine == InventTransferLine::find(this.InventTransId, this.LineNum).RecId;
        select firstonly metTransLine where metTransLine.InventTransferLine == this.RecId;
        InventTransferLine invLine = InventTransferLine::findRecId(metTransLine.InventTransferLine);


        select sum(Qty) from views where views.ReferenceId == invLine.TransferId
            && views.inventTransId == invLine.InventTransId
            && views.StatusIssue == StatusIssue::ReservPhysical;
        inventqty  reservedQty = (abs(views.Qty));

        Factor factor = EcoResProductUnitConverter::convertForReleasedProduct(
                        this.ItemId,
                        this.inventDimId,
                        1,
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(unitInvent),
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(metTransLine.warehouseUnitId),
                        NoYes::No,
                        NoYes::No);


        METCase actualCase = any2Int(metTransLine.WarehouseUnitId == METConstants::unitEach ? 0 : (factor * reservedQty));
        
        return real2int(reservedQty-(actualCase*(1/factor)));

    }

    /// <summary>
    /// To get ActualUnitVolume for the SalesLine Item.
    /// </summary>
    /// <returns>unitVolume of salesLine Item</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display METUOMVolume displayMETActualUnitVolume()
    {
        
        InventQty               actBrokenCase   = this.displayMETActualBrokenCase();
        InventQty               actCase         = this.displayMETActualCases();
        UnitOfMeasureSymbol     unitInvent      = InventTableModule::find(this.itemId, ModuleInventPurchSales::Invent).UnitId;
        //UnitOfMeasureSymbol     unitSales       = this.SalesUnit;
        METInventTransferLine   metTransLine;
        select firstonly metTransLine where metTransLine.InventTransferLine == this.RecId;

        return (METWHSPhysDimUOMSite::convertVolume(this.ItemId, actCase, metTransLine.WarehouseUnitId, this.inventDim())
                    + METWHSPhysDimUOMSite::convertVolume(this.ItemId, actBrokenCase, unitInvent, this.inventDim()));
    }

    /// <summary>
    /// To get actualWeight for the SalesLine Item.
    /// </summary>
    /// <returns>ActualWeight of salesLine Item</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display METGrossWeight displayMETActualWeight()
    {
        
        //UnitOfMeasureSymbol     unitSales       = this.SalesUnit;
        UnitOfMeasureSymbol     unitInvent      = InventTableModule::find(this.itemId, ModuleInventPurchSales::Invent).UnitId;
        InventQty               actBrokenCase   = this.displayMETActualBrokenCase();
        InventQty               actCase         = this.displayMETActualCases();

        METInventTransferLine   metTransLine;
        select firstonly metTransLine where metTransLine.InventTransferLine == this.RecId;

        return (METWHSPhysDimUOMSite::convertWeight(this.ItemId, actCase, metTransLine.WarehouseUnitId, this.inventDim())
                    + METWHSPhysDimUOMSite::convertWeight(this.ItemId, actBrokenCase, unitInvent, this.inventDim()));
    }

    /// <summary>
    /// Calculate actual total number of cases for the sales order line quantity.
    /// </summary>
    /// <returns>Total cases of salesLine Item</returns>
    [SysClientCacheDataMethod(true)]
    public display InventQty metActualTotalcases()
    {
        UnitOfMeasureSymbol     unitInvent          = InventTableModule::find(this.itemId, ModuleInventPurchSales::Invent).UnitId;
        METInventTransView      views;
        METInventTransferLine   metTransLine;
        //select metTransLine where metTransLine.InventTransferLine == InventTransferLine::find(this.InventTransId, this.LineNum).RecId;
        select firstonly metTransLine where metTransLine.InventTransferLine == this.RecId;

        select sum(Qty) from views where views.ReferenceId == this.TransferId
                && views.inventTransId == this.InventTransId
                && views.StatusIssue == StatusIssue::ReservPhysical;
        inventqty  reservedQty = (abs(views.Qty));

        Factor factor = EcoResProductUnitConverter::convertForReleasedProduct(
                        this.ItemId,
                        this.inventDimId,
                        1,
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(unitInvent),
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(metTransLine.WarehouseUnitId),
                        NoYes::No,
                        NoYes::No);
        
        return metTransLine.WarehouseUnitId == METConstants::unitEach ? 0 : (factor * reservedQty);
    }
